-- Phase 89: Process Intelligence / Process Mining (analytical only)
create table public.process_intelligence_member_permissions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,permission_key text not null,granted_at timestamptz not null default now(),unique(organization_id,user_id,permission_key));
create table public.process_definitions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,process_key text not null,name text not null,description text not null default '',domain text not null,process_type text not null default 'operational',owner_label text not null,status text not null default 'draft' check(status in('draft','active','paused','archived')),start_activity_key text,end_activity_key text,analytical_only boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,process_key));
create table public.process_case_definitions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,process_id uuid not null references public.process_definitions(id) on delete cascade,version integer not null default 1,case_key_expression text not null,completion_rule jsonb not null default '{}',active boolean not null default true,created_at timestamptz not null default now(),unique(process_id,version));
create table public.process_subtypes(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,process_id uuid not null references public.process_definitions(id) on delete cascade,subtype_key text not null,name text not null,filter_definition jsonb not null default '{}',active boolean not null default true,unique(process_id,subtype_key));
create table public.process_activities(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,process_id uuid not null references public.process_definitions(id) on delete cascade,activity_key text not null,name text not null,activity_group text not null default 'work',required boolean not null default false,expected_retry boolean not null default false,unique(process_id,activity_key));
create table public.process_event_mappings(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,process_id uuid not null references public.process_definitions(id) on delete cascade,source_domain text not null,source_event_type text not null,activity_key text not null,version integer not null default 1,status text not null default 'draft' check(status in('draft','published','retired')),mapping_definition jsonb not null default '{}',published_at timestamptz,created_at timestamptz not null default now(),unique(process_id,source_domain,source_event_type,version));
create table public.process_event_log(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,process_id uuid not null references public.process_definitions(id) on delete cascade,case_id text not null,activity_key text not null,event_time timestamptz not null,ingest_time timestamptz not null default now(),source_domain text not null,source_event_type text not null,source_ref text not null,source_event_id text,sequence_no bigint,quality text not null default 'authoritative' check(quality in('authoritative','inferred_from_state_transition','reconstructed','partial','unknown')),store_id uuid references public.establishments(id) on delete set null,region_id uuid,channel text,safe_attributes jsonb not null default '{}',mapping_version integer not null default 1,created_at timestamptz not null default now(),check(jsonb_typeof(safe_attributes)='object'));
create unique index process_event_log_dedup_idx on public.process_event_log(organization_id,source_domain,source_event_id) where source_event_id is not null;
create table public.process_event_quarantine(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,process_id uuid references public.process_definitions(id) on delete cascade,source_domain text not null,source_ref text not null,issue_code text not null,safe_metadata jsonb not null default '{}',status text not null default 'open',created_at timestamptz not null default now(),resolved_at timestamptz);
create table public.process_case_states(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,process_id uuid not null references public.process_definitions(id) on delete cascade,case_id text not null,status text not null default 'open' check(status in('open','completed','failed','abandoned','incomplete','unknown')),first_event_at timestamptz,last_event_at timestamptz,event_count integer not null default 0,coverage_quality text not null default 'unknown',recompute_required boolean not null default false,updated_at timestamptz not null default now(),unique(organization_id,process_id,case_id));
create table public.process_models(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,process_id uuid not null references public.process_definitions(id) on delete cascade,model_type text not null check(model_type in('discovered','expected')),name text not null,status text not null default 'draft',created_at timestamptz not null default now());
create table public.process_model_versions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,model_id uuid not null references public.process_models(id) on delete cascade,version integer not null,definition jsonb not null,method text not null default 'deterministic_dfg',sample_size bigint not null default 0,coverage numeric(7,6),published_at timestamptz,unique(model_id,version));
create table public.process_variants(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,process_id uuid not null references public.process_definitions(id) on delete cascade,analysis_run_id uuid,variant_hash text not null,activity_sequence jsonb not null,case_count bigint not null default 0,case_share numeric(7,6) not null default 0,median_cycle_time_ms bigint not null default 0,rework_cases bigint not null default 0,failure_cases bigint not null default 0,created_at timestamptz not null default now());
create table public.process_analysis_runs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,process_id uuid not null references public.process_definitions(id) on delete cascade,analysis_type text not null,period_start timestamptz not null,period_end timestamptz not null,status text not null default 'queued',input_version text not null,method_version text not null,sample_size bigint not null default 0,coverage numeric(7,6),started_at timestamptz,completed_at timestamptz,error_code text,created_at timestamptz not null default now());
alter table public.process_variants add constraint process_variants_run_fk foreign key(analysis_run_id) references public.process_analysis_runs(id) on delete cascade;
create table public.process_analysis_jobs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,analysis_run_id uuid not null references public.process_analysis_runs(id) on delete cascade,job_type text not null,status text not null default 'queued',attempt_count integer not null default 0,available_at timestamptz not null default now(),lease_expires_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.process_transition_aggregates(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,analysis_run_id uuid not null references public.process_analysis_runs(id) on delete cascade,from_activity_key text not null,to_activity_key text not null,transition_count bigint not null,case_count bigint not null,case_share numeric(7,6) not null,median_delay_ms bigint not null,p90_delay_ms bigint not null);
create table public.process_cycle_time_aggregates(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,analysis_run_id uuid not null references public.process_analysis_runs(id) on delete cascade,dimension_key text not null default 'all',dimension_value text not null default 'all',eligible_cases bigint not null,open_cases_excluded bigint not null,p50_ms bigint not null,p75_ms bigint not null,p90_ms bigint not null,p95_ms bigint not null,median_waiting_ms bigint not null default 0);
create table public.process_bottlenecks(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,analysis_run_id uuid not null references public.process_analysis_runs(id) on delete cascade,from_activity_key text not null,to_activity_key text not null,bottleneck_type text not null,median_delay_ms bigint not null,p90_delay_ms bigint not null,evidence jsonb not null default '{}',detected_at timestamptz not null default now());
create table public.process_rework_findings(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,analysis_run_id uuid not null references public.process_analysis_runs(id) on delete cascade,activity_key text not null,rework_count bigint not null,case_rate numeric(7,6) not null,expected_retry_excluded boolean not null default true,evidence jsonb not null default '{}');
create table public.process_conformance_findings(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,analysis_run_id uuid not null references public.process_analysis_runs(id) on delete cascade,case_id text,deviation_type text not null,severity text not null,activity_key text,evidence jsonb not null default '{}',created_at timestamptz not null default now());
create table public.process_peer_groups(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,scope_definition jsonb not null,minimum_sample_size integer not null default 10,created_at timestamptz not null default now());
create table public.process_baselines(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,process_id uuid not null references public.process_definitions(id) on delete cascade,name text not null,period_start timestamptz not null,period_end timestamptz not null,metrics jsonb not null,created_at timestamptz not null default now());
create table public.process_change_markers(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,process_id uuid not null references public.process_definitions(id) on delete cascade,change_id uuid,marker_at timestamptz not null,label text not null,safe_metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table public.process_improvement_opportunities(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,process_id uuid not null references public.process_definitions(id) on delete cascade,analysis_run_id uuid references public.process_analysis_runs(id) on delete set null,opportunity_type text not null,title text not null,finding text not null,evidence jsonb not null,confidence text not null check(confidence in('low','medium','high')),status text not null default 'detected' check(status in('detected','reviewed','accepted','rejected','draft_created')),automation_draft_id uuid,auto_execute boolean not null default false,created_at timestamptz not null default now(),reviewed_at timestamptz);
create table public.process_reviews(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,opportunity_id uuid not null references public.process_improvement_opportunities(id) on delete cascade,decision text not null,notes text not null default '',reviewer_id uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create table public.process_audit_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,actor_id uuid references auth.users(id) on delete set null,action text not null,resource_type text not null,resource_id text,correlation_id text,safe_metadata jsonb not null default '{}',created_at timestamptz not null default now());

-- quality: allow-nonconcurrent-index reason=new-empty-process-intelligence-tables
create index process_event_log_case_idx on public.process_event_log(organization_id,process_id,case_id,event_time,sequence_no);
create index process_event_log_analysis_idx on public.process_event_log(organization_id,process_id,event_time,activity_key);
create index process_case_states_status_idx on public.process_case_states(organization_id,process_id,status,last_event_at desc);
create index process_analysis_runs_lookup_idx on public.process_analysis_runs(organization_id,process_id,analysis_type,period_end desc);
create index process_analysis_jobs_queue_idx on public.process_analysis_jobs(status,available_at,lease_expires_at);
create index process_opportunities_status_idx on public.process_improvement_opportunities(organization_id,status,created_at desc);
create index process_audit_events_lookup_idx on public.process_audit_events(organization_id,created_at desc);

create view public.process_intelligence_overview with(security_invoker=true) as select organization_id,process_id,count(*) filter(where status='completed') as completed_cases,count(*) filter(where status='open') as open_cases,count(*) as total_cases,max(last_event_at) as last_event_at from public.process_case_states group by organization_id,process_id;

do $$declare t text;begin foreach t in array array['process_intelligence_member_permissions','process_definitions','process_case_definitions','process_subtypes','process_activities','process_event_mappings','process_event_log','process_event_quarantine','process_case_states','process_models','process_model_versions','process_variants','process_analysis_runs','process_analysis_jobs','process_transition_aggregates','process_cycle_time_aggregates','process_bottlenecks','process_rework_findings','process_conformance_findings','process_peer_groups','process_baselines','process_change_markers','process_improvement_opportunities','process_reviews','process_audit_events'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
revoke all on public.process_intelligence_overview from public,anon,authenticated;grant select on public.process_intelligence_overview to service_role;

insert into public.feature_definitions(feature_key,name,description,category,value_type,default_value,safe_default,client_safe,owner_label,lifecycle_status,created_at,updated_at) values
('process_intelligence_enabled','Process Intelligence','Ativa análises de processos assíncronas.','analytics','boolean','false','false',false,'Data Platform','active',now(),now()),
('process_discovery_enabled','Process Discovery','Ativa descoberta determinística de fluxo.','analytics','boolean','false','false',false,'Data Platform','active',now(),now()),
('process_conformance_enabled','Process Conformance','Ativa comparação com modelo esperado.','analytics','boolean','false','false',false,'Data Governance','active',now(),now()),
('process_improvement_detection_enabled','Process Improvement Detection','Ativa detecção de oportunidades sem execução automática.','analytics','boolean','false','false',false,'Operations Excellence','active',now(),now()) on conflict(feature_key) do update set name=excluded.name,description=excluded.description,updated_at=now();

